FAssetRow UKeyTypesLibrary::GetAssetRow(FGuid Key, bool& bFound)
{
    const FAssetRow* Found = FKeyTypes::Asset().FindByIndex(Key);

    bFound = Found != nullptr;

    // A copy, because Blueprint takes a struct by value and the row belongs to the table.
    // A default one when the key is not there, which is why bFound is not decoration.
    return Found != nullptr ? *Found : FAssetRow();
}

int32 UKeyTypesLibrary::GetAssetRowCount()
{
    return FKeyTypes::Asset().Records().Num();
}

FAssetRow UKeyTypesLibrary::GetAssetRowAt(int32 Position, bool& bFound)
{
    const TArray<FAssetRow>& Rows = FKeyTypes::Asset().Records();

    bFound = Rows.IsValidIndex(Position);

    return bFound ? Rows[Position] : FAssetRow();
}


