bool UKeyTypesLibrary::ReadAll(const FString& BasePath, const FString& FileExtension)
{
    return FKeyTypes::ReadAll(BasePath, FileExtension);
}

bool FKeyTypes::ReadAll(const FString& BasePath, const FString& FileExtension)
{
    // Read into tables of their own and moved into place at the end. Reading again is a
    // refresh - a patched .pak, a downloaded table - and one that fails on the third file
    // must not leave the first two replaced and the rest as they were.
    FAssetTable LoadedAsset;

    if (!LoadedAsset.Read(FPaths::Combine(BasePath, TEXT("Asset") + FileExtension)))
    {
        return false;
    }
    FLedgerTable LoadedLedger;

    if (!LoadedLedger.Read(FPaths::Combine(BasePath, TEXT("Ledger") + FileExtension)))
    {
        return false;
    }
    FSlottingTable LoadedSlotting;

    if (!LoadedSlotting.Read(FPaths::Combine(BasePath, TEXT("Slotting") + FileExtension)))
    {
        return false;
    }

    AssetStorage = MoveTemp(LoadedAsset);
    LedgerStorage = MoveTemp(LoadedLedger);
    SlottingStorage = MoveTemp(LoadedSlotting);

    return true;
}
